        if ( nVars < 8 )
            pStore[nVars-1] += pResC[nVars-1];
        return (int)pResC[7];
    }
    else
    {
        int Res1 = Abc_TtCountOnesInCofsQuick_rec( pTruth,                    nVars-1, pStore );
        int Res2 = Abc_TtCountOnesInCofsQuick_rec( pTruth + (1 << (nVars-7)), nVars-1, pStore );
        pStore[nVars-1] = Res1;
        return Res1 + Res2;
    }
}

